import{z as B,x as p,o as t,c as A,q as s,j as E,D as e,d as i,s as l,S as r,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"原生分辨率 ViT","description":"","frontmatter":{"title":"原生分辨率 ViT","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/native-resolution-vit.md","filePath":"llm/native-resolution-vit.md","lastUpdated":1791063341000}'),d={name:"llm/native-resolution-vit.md"};function m(h,a,D,T,u,c){const o=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="原生分辨率-vit" tabindex="-1">原生分辨率 ViT <a class="header-anchor" href="#原生分辨率-vit" aria-label="Permalink to &quot;原生分辨率 ViT&quot;">​</a></h1><div class="epigraph"><p>把任意高宽的图 squish 到 224 方形，表格与路牌先死在编码器里。位置编码与切块必须承认二维可变网格。</p><footer>—— Dehghani 等 NaViT；动态分辨率实践见 [Qwen2-VL](/llm/qwen-vl-naive-dynamic-res) 与 [AnyRes](/llm/anyres)</footer></div><p><a href="/llm/continuous-vs-discrete-vision-tokens">上一课</a>选定理解侧走连续 patch。主干 ViT 课已写固定边长的位置嵌入。本课写原生分辨率：可变 \\(H,W\\)，token 数随图变。缺口是画布假设。后课 2D RoPE 提供位置编码的一种实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分类 ViT 假设固定 \\(N\\)。VLM 要读文档、屏幕、非方形照片。强制 resize 破坏长宽比；padding 浪费上下文。AnyRes 把图切成多块分别过固定 ViT，再拼接——分辨率来自拼块，位置关系要另编码。NaViT 在同一 ViT 里对可变序列做打包训练，补位与掩码处理不同 \\(N\\)。Qwen2-VL 一类动态分辨率把原生切块 + 二维位置做成产品默认。</p><p>token 税：\\(N\\approx HW/P^2\\) 直接占 LLM 上下文，必须与<a href="/llm/vision-token-compression">视觉 token 压缩</a>一起预算。</p><p><span class="marginnote">原生分辨率不是无限分辨率。仍有上限 \\(N_{\\max}\\)，超大图要切页或降采样，只是不再强行方形。</span></p><p><span class="marginnote">patch 可以翻译成「视觉单词」：把图切成 \\(P\\times P\\) 的小方块，每块当成一个词喂给模型。token 税代个数字：一张 \\(800\\times300\\) 的截图按 \\(P=16\\) 切块，约 \\(50\\times19\\approx950\\) 个 token——这些「词」全要挤进 LLM 上下文，和几千字的 prompt 抢同一个预算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现清单：可变长注意力掩码；二维位置（下一课）；打包多个不同分辨率图进同一批（NaViT 的效率点）；与 LLM 的接口声明最大视觉 token。评测用文档 OCR、截图、非方形图，不用只 squish 过的 ImageNet。</p>',10)),(t(),E(r,null,{default:e(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E4%BB%BB%E6%84%8F%20H%20x%20W%22%5D%20--%3E%20PATCH%5B%22P%20x%20P%20%E5%88%87%E5%9D%97%22%5D%0A%20%20PATCH%20--%3E%20POS%5B%22%E4%BA%8C%E7%BB%B4%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20VIT%5B%22%E5%8F%AF%E5%8F%98%E9%95%BF%20ViT%22%5D%0A%20%20VIT%20--%3E%20N%5B%22N%20%E4%B8%AA%E8%BF%9E%E7%BB%AD%20token%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[i("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"固定位置嵌入把第 \\(i\\) 个 token 当成「224 画布上的第 \\(i\\) 格」。分辨率一变，格的物理意义变了，插值只是权宜。原生网格让格子对应真实 patch 坐标，注意力才能学到「右上角表头」。打包训练迫使模型在不同 \\(N\\) 上共享权重，避免只在 224 上过拟合。",-1)),(t(),E(r,null,{default:e(()=>[l(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E8%A1%A8%E6%A0%BC%E6%88%AA%E5%9B%BE%20800%20x%20300%22%5D%20--%3E%20SQ%5B%22%E6%96%B9%E6%A1%88%E4%B8%80%20squish%20%E6%88%90%20224%20%E6%96%B9%E5%BD%A2%22%5D%0A%20%20SRC%20--%3E%20PAD%5B%22%E6%96%B9%E6%A1%88%E4%BA%8C%20padding%20%E8%A1%A5%E6%88%90%E6%96%B9%E5%BD%A2%22%5D%0A%20%20SRC%20--%3E%20NAT%5B%22%E6%96%B9%E6%A1%88%E4%B8%89%20%E5%8E%9F%E7%94%9F%E7%BD%91%E6%A0%BC%E5%88%87%E5%9D%97%22%5D%0A%20%20SQ%20--%3E%20LOSE%5B%22%E9%95%BF%E5%AE%BD%E6%AF%94%E5%8E%8B%E6%89%81%20%E5%AD%97%E8%BF%B9%E7%B2%98%E8%BF%9E%22%5D%0A%20%20PAD%20--%3E%20WASTE%5B%22%E5%A4%A7%E7%89%87%E7%A9%BA%E7%99%BD%20%E7%99%BD%E8%8A%B1%20token%22%5D%0A%20%20NAT%20--%3E%20KEEP%5B%22%E7%BA%A6%2050%20x%2019%20%E7%BD%91%E6%A0%BC%20%E4%BF%9D%E4%BD%8F%E6%AF%94%E4%BE%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">初学者容易以为插值位置嵌入是「免费扩展」：把 224 网格的位置表拉伸到 448 就能用。实际上插值只保证「不报错」，格子与真实像素的对应关系已经断了——好比把世界地图硬拉成另一比例，城市名都还在，距离全错了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可变 \\(N\\) 让 KV 缓存与编译形状变难，服务要动态分桶。下一课把二维相对位置写成 RoPE 的推广。</p><p><span class="marginnote">为什么要动态分桶：注意力显存大约随 token 数平方增长，一张 4K 截图可能带来几千个视觉 token，请求形状千变万化，编译器每见一个新形状就要重编译。把请求按 token 数归进几个预设「桶」（如 1024 / 2048 / 4096），每个桶只需编译一次，短请求多补一点 padding 就能共用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原生分辨率保留长宽比与表格结构，token 数随图变。</li><li>必须配二维位置与可变长掩码；有 \\(N_{\\max}\\)。</li><li>用文档与截图评测，不用 squish 分类榜。</li><li>出处：Dehghani 等 NaViT；AnyRes；Qwen2-VL 动态分辨率。</li></ul>',6))])}const P=B(d,[["render",m]]);export{_ as __pageData,P as default};
